import { createHash } from "node:crypto";

/** The four sections which can be projected from a Working Context snapshot. */
export type RecoverySectionName =
  | "goals"
  | "unfinishedWork"
  | "recentEvidence"n  | "dependencies";

export type RecoverySection = {
  name: RecoverySectionName;
  items: string[];
  kept: number;
  dropped: number;
  truncated: boolean;
};

export type WorkingContextSnapshot = {
  goals?: unknown[];
  unfinishedWork?: unknown[];
  dependencies?: unknown[];
  recentEvidence?: unknown[];
};

export type ContextPressureRecoveryOptions = {
  maxDepth: number;
  maxItemsPerSection?: number;
  /** Maximum depth is deliberately a hard boundary; recursion is never followed. */
  currentDepth?: number;
};

export type ContextPressureRecoveryResult =
  | {
      status: "recovered";
      complete: false;
      depth: number;
      digest: string;
      sections: Record<RecoverySectionName, RecoverySection>;
      totalKept: number;
      totalDropped: number;
      truncated: boolean;
    }
  | {
      status: "unknown";
      complete: false;
      depth: number;
      digest: string;
      sections: null;
      totalKept: 0;
      totalDropped: 0;
      truncated: false;
    }
  | {
      status: "depth-exceeded";
      complete: false;
      depth: number;
      digest: string;
      sections: null;
      totalKept: 0;
      totalDropped: 0;
      truncated: false;
    };

const SECTION_NAMES: RecoverySectionName[] = [
  "goals",
  "unfinishedWork",
  "dependencies",
  "recentEvidence",
];

function canonical(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`;
  const record = value as Record<string, unknown>;
  return `{${Object.keys(record).sort().map((key) => `${JSON.stringify(key)}:${canonical(record[key])}`).join(",")}}`;
}

function digestOf(value: unknown): string {
  return createHash("sha256").update(canonical(value)).digest("hex");
}

function textOf(value: unknown): string {
  if (typeof value === "string") return value;
  try {
    return canonical(value);
  } catch {
    return String(value);
  }
}

function emptyResult(status: "unknown" | "depth-exceeded", depth: number): ContextPressureRecoveryResult {
  return {
    status,
    complete: false,
    depth,
    digest: digestOf({ status, depth }),
    sections: null,
    totalKept: 0,
    totalDropped: 0,
    truncated: false,
  };
}

/**
 * Project a bounded, deterministic recovery summary from a Working Context snapshot.
 *
 * The function never follows nested snapshots and never reports completion. A caller
 * must explicitly opt into recovery by supplying a bounded depth.
 */
export function recoverContextPressure(
  snapshot: WorkingContextSnapshot | null | undefined,
  options: ContextPressureRecoveryOptions,
): ContextPressureRecoveryResult {
  const depth = options.currentDepth ?? 0;
  if (!Number.isInteger(options.maxDepth) || options.maxDepth < 0 || depth > options.maxDepth) {
    return emptyResult("depth-exceeded", depth);
  }
  if (!snapshot || typeof snapshot !== "object") return emptyResult("unknown", depth);

  const budget = options.maxItemsPerSection ?? 32;
  if (!Number.isInteger(budget) || budget < 0) return emptyResult("unknown", depth);

  const sections = {} as Record<RecoverySectionName, RecoverySection>;
  for (const name of SECTION_NAMES) {
    const source = Array.isArray(snapshot[name]) ? snapshot[name] : [];
    const kept = source.slice(0, budget).map(textOf);
    const dropped = Math.max(0, source.length - kept.length);
    sections[name] = {
      name,
      items: kept,
      kept: kept.length,
      dropped,
      truncated: dropped > 0,
    };
  }

  const totalKept = SECTION_NAMES.reduce((sum, name) => sum + sections[name].kept, 0);
  const totalDropped = SECTION_NAMES.reduce((sum, name) => sum + sections[name].dropped, 0);
  const truncated = totalDropped > 0;
  const payload = {
    status: "recovered" as const,
    depth,
    sections,
    totalKept,
    totalDropped,
    truncated,
  };
  return { ...payload, complete: false, digest: digestOf(payload) };
}

export const projectContextPressureRecovery = recoverContextPressure;

export default recoverContextPressure;

